entries[65791] = { ["name"] = "Arkanschlag", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Energie und verursacht 12488 to 14512 Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller Arkanzauber um 15% und die Manakosten von 'Arkanschlag' um 175% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 sec lang an oder bis ein Arkanzauber außer 'Arkanschlag' gewirkt wurde." }
entries[65792] = { ["name"] = "Frostnova", ["text"] = "8% von Grundmana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden 365 to 415 Frostschaden zu und friert sie bis zu 8 sec lang ein. Erlittener Schaden kann den Effekt unterbrechen." }
entries[65793] = { ["name"] = "Blinzeln", ["text"] = "21% von Grundmana\nSofort 15 sek. Abklingzeit\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Fesseln." }
