entries[65800] = { ["name"] = "Arkane Explosion", ["text"] = "22% von Grundmana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 5280 to 5720 Arkanschaden zu." }
entries[65801] = { ["name"] = "Verwandlung", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nVerwandelt den Feind in ein Schaf und zwingt ihn, 10 sec lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[65802] = { ["name"] = "Eisblock", ["text"] = "15 Mana\nSofort 5 min Abklingzeit\nIhr werdet in einen Eisblock eingehüllt, der Euch 5 sec lang vor allen körperlichen Angriffen und Zaubern schützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Verursacht ebenfalls 'Unterkühlung' und verhindert 30 sec lang, dass 'Eisblock' gewirkt werden kann." }
entries[65807] = { ["name"] = "Frostblitz", ["text"] = "13% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Frostblitz auf den Feind, der 11563 to 13437 Frostschaden verursacht und 9 sec lang das Bewegungstempo um 40% reduziert." }
entries[65808] = { ["name"] = "Entfesselte Nacht", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie konzentrierte Nacht entfesselt ihre Energien und fügt Gegnern innerhalb von 6 Metern 14625 to 15375 Nachtschaden zu." }
entries[65809] = { ["name"] = "Furcht", ["text"] = "12% von Grundmana 20 Meter Reichweite\nWirken in 1.5 sek. 8 sek. Abklingzeit\nErfüllt den Feind mit Furcht, woraufhin er bis zu 10 sec lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[65810] = { ["name"] = "Verderbnis", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nVerdirbt das Ziel und verursacht 18 sec lang insgesamt 30000 Schattenschaden." }
entries[65811] = { ["name"] = "Essenz des Lichts" }
entries[65812] = { ["name"] = "Instabiles Gebrechen", ["text"] = "15% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nSchattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 15 sec 23125 to 26875 Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 to 16125 Schattenschaden und wird 5 sec lang zum Schweigen gebracht." }
entries[65813] = { ["name"] = "Instabiles Gebrechen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende 13875 to 16125 Schattenschaden und wird 5 sec lang zum Schweigen gebracht." }
entries[65814] = { ["name"] = "Fluch der Pein", ["text"] = "10% von Grundmana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 42000 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[65815] = { ["name"] = "Fluch der Erschöpfung", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort\nVerringert das Bewegungstempo des Ziels 12 sec lang um 50%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[65816] = { ["name"] = "Höllenfeuer", ["text"] = "64% von Grundmana\nKanalisiert (Wirken in 15 sek.)\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 sec lang an." }
entries[65817] = { ["name"] = "Höllenfeuereffekt", ["text"] = "Sofort\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 1500 Feuerschaden zu sowie im gleichen Rhythmus allen in der Nähe befindlichen Feinden 9000 Feuerschaden. Hält 15 sec lang an." }
entries[65819] = { ["name"] = "Sengender Schmerz", ["text"] = "8% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel sengenden Schmerz zu und verursacht 5490 to 6510 Feuerschaden. Verursacht ein hohes Maß an Bedrohung." }
entries[65820] = { ["name"] = "Todesmantel", ["text"] = "23% von Grundmana 30 Meter Reichweite\nSofort 2 min Abklingzeit\nVerursacht 9425 to 10575 Schattenschaden und das betroffene Ziel läuft 3 sec lang voller Entsetzen davon. Der Zaubernde erhält 500% des verursachten Schadens in Gesundheit." }
entries[65821] = { ["name"] = "Schattenblitz", ["text"] = "17% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Schattenblitz auf den Feind und verursacht 11813 to 13187 Schattenschaden." }
entries[65825] = { ["name"] = "Flughafenbanner" }
entries[65826] = { ["name"] = "Dockbanner" }
entries[65827] = { ["name"] = "Essenz der Nacht" }
entries[65828] = { ["name"] = "Geschwindigkeitsschub", ["text"] = "Sofort\nErhöht das Bewegungstempo 10 sec lang um 70%." }
entries[65854] = { ["name"] = "Sternenfeuer", ["text"] = "16% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nFügt dem Ziel 12387 to 14613 Arkanschaden zu." }
entries[65855] = { ["name"] = "Insektenschwarm", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nDas feindliche Ziel wird von Insekten umschwärmt, die dessen Trefferchance mit Nahkampf- und Distanzangriffen um 3% verringern und beim Betroffenen über 12 sec 22200 to 25800 Naturschaden verursachen." }
entries[65856] = { ["name"] = "Mondfeuer", ["text"] = "21% von Grundmana 30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nVerbrennt den Feind und fügt ihm 4140 to 4860 Arkanschaden sowie 12 sec lang insgesamt 7000 zusätzlichen Arkanschaden zu." }
entries[65857] = { ["name"] = "Wucherwurzeln", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 10 sek. Abklingzeit\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht im Verlauf von 10 sec insgesamt 1576.7 to 1756.7 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen." }
entries[65858] = { ["name"] = "Schild des Lichts", ["text"] = "Sofort\nEin heller Schild schützt die Schwester, absorbiert 1200000 Schaden und verhindert 16 sec lang das Unterbrechen von Zaubern." }
entries[65859] = { ["name"] = "Wirbelsturm", ["text"] = "8% von Grundmana 20 Meter Reichweite\nWirken in 1.5 sek. 6 sek. Abklingzeit\nWirbelt das Ziel bis zu 6 sec lang in die Luft. Während dieser Zeit ist es handlungsunfähig, aber auch unverwundbar. Es kann immer nur ein Ziel gleichzeitig von Eurem Zauber 'Wirbelsturm' betroffen sein." }
entries[65860] = { ["name"] = "Baumrinde", ["text"] = "Sofort 1 min Abklingzeit\nDie Haut des Druiden wird hart wie Rinde. Jeglicher erlittene Schaden wird um 40% verringert. Kann auch gewirkt werden, wenn man betäubt, eingefroren, handlungsunfähig oder in Schlaf versetzt worden ist oder sich fürchtet. In allen Gestalten nutzbar. Hält 12 sec lang an." }
entries[65861] = { ["name"] = "Naturgewalt", ["text"] = "12% von Grundmana 30 Meter Reichweite\nSofort 3 min Abklingzeit\nBeschwört 3 Treants, die das Ziel 30 sec lang angreifen." }
entries[65862] = { ["name"] = "Zorn", ["text"] = "11% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem Ziel 8460 to 9540 Naturschaden zu." }
entries[65863] = { ["name"] = "Feenfeuer", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 sec lang um 15%. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[65866] = { ["name"] = "Explosivschuss", ["text"] = "7% von Grundmana 35 Meter Reichweite\n6 sek. Abklingzeit\nBenötigt Distanzwaffe\nFeuert ein Explosivgeschoss in das Ziel, das 4533 to 5467 Feuerschaden verursacht. Die Sprengladung verursacht 2 sec lang pro Sekunde weiteren Schaden." }
entries[65867] = { ["name"] = "Zuverlässiger Schuss", ["text"] = "5% von Grundmana 35 Meter Reichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin zuverlässiger Schuss, der einem Ziel Waffenschaden zufügt." }
entries[65868] = { ["name"] = "Schießen", ["text"] = "45 Meter Reichweite\nWirken in 1.7 sek.\nBenötigt Distanzwaffe\nSchießt auf den Feind und fügt körperlichen Schaden zu." }
entries[65869] = { ["name"] = "Rückzug", ["text"] = "5% von Grundmana 10 Meter Reichweite\nSofort 30 sek. Abklingzeit\nIhr versucht, Euch mit einem Rückwärtssprung vom Ziel zurückzuziehen." }
entries[65870] = { ["name"] = "Rückzug" }
entries[65871] = { ["name"] = "Abschreckung", ["text"] = "Sofort 1.5 min Abklingzeit\nBenötigt Nahkampfwaffe\nErhöht bei Aktivierung Eure Parierchance um 100% und gewährt Euch eine Chance von 100%, Zauber von vor Euch befindlichen Zielen abzuwehren. Hält 5 sec lang an." }
entries[65872] = { ["name"] = "Permafrost" }
entries[65874] = { ["name"] = "Schild der Nacht", ["text"] = "Sofort\nEin dunkler Schild schützt die Schwester, absorbiert 1200000 Schaden und verhindert 16 sec lang das Unterbrechen von Zaubern." }
entries[65875] = { ["name"] = "Zwillingspakt", ["text"] = "Unbegrenzte Reichweite\nWirken in 15 sek.\nDer Zwillingspakt heilt die Zwillinge um 50% ihrer gesamten Gesundheit." }
entries[65876] = { ["name"] = "Zwillingspakt", ["text"] = "Unbegrenzte Reichweite\nWirken in 15 sek.\nDer Zwillingspakt heilt die Zwillinge um 50% ihrer gesamten Gesundheit." }
entries[65877] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "8% von Grundmana 35 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nVerschießt einen Stachel, der das Ziel 8 sec lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 sec insgesamt 2460 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[65878] = { ["name"] = "Stich des Flügeldrachen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerschießt einen Stachel, der das Ziel 30 sec lang einschläfert. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Wenn das Ziel wieder aufwacht, verursacht der Stich im Verlauf von 6 sec insgesamt 2460 Naturschaden. Auf dem Ziel kann gleichzeitig nur ein Biss oder Stich pro Jäger aktiv sein." }
entries[65879] = { ["name"] = "Macht der Zwillinge", ["text"] = "Sofort\nDie geteilte Macht der Zwillinge erhöht ihren verursachten körperlichen Schaden um 20% und gestattet es ihnen 15 sec lang, Waffen beidhändig zu nutzen.\n(500ms Abklingzeit)" }
entries[65880] = { ["name"] = "Frostfalle", ["text"] = "2% von Grundmana\nSofort 30 sek. Abklingzeit\nEine Frostfalle platzieren, die 30 sec lang um sich herum eine Eisfläche bildet, sobald der erste Feind sich ihr nähert. Das Bewegungstempo aller Feinde in einem Umkreis von 10 Metern wird um 50% verlangsamt, solange sie sich im Wirkungsbereich befinden. Die Falle bleibt 30 sec lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[65881] = { ["name"] = "Vipernbiss", ["text"] = "270 Mana 35 Meter Reichweite\n15 sek. Abklingzeit\nBeißt das Ziel und zieht 8 sec lang 9600 Mana ab. Es kann immer nur jeweils ein Biss oder Stich pro Jäger auf einem beliebigen Ziel aktiv sein." }
entries[65882] = { ["name"] = "Permafrost" }
entries[65883] = { ["name"] = "Gezielter Schuss", ["text"] = "8% von Grundmana 35 Meter Reichweite\n10 sek. Abklingzeit\nBenötigt Distanzwaffe\nEin gezielter Schuss, der den Distanzschaden um 6000 erhöht und auf das Ziel gewirkte Heileffekte um 50% verringert. Hält 10 sec lang an." }
entries[65916] = { ["name"] = "Macht der Zwillinge", ["text"] = "Sofort\nDie geteilte Macht der Zwillinge erhöht ihren verursachten körperlichen Schaden um 20% und gestattet es ihnen 15 sec lang, Waffen beidhändig zu nutzen.\n(500ms Abklingzeit)" }
entries[65917] = { ["name"] = "Magischer Hahn", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren magischen Hahn und gibt ihn wieder frei. Nein, ehrlich! Das ist ein sehr schnelles Reittier." }
entries[65918] = { ["name"] = "Betäubt", ["text"] = "Unbegrenzte Reichweite\nSofort\nVom Reittier gestoßen zu werden, betäubt das Ziel 10 sec lang." }
entries[65919] = { ["name"] = "Durchbohren", ["text"] = "6 Meter Reichweite\nSofort\nFeuert Stachel durch den Boden oberhalb von Anub'arak, was 17672 to 19828 körperlichen Schaden an jedem Ziel verursacht, das in ihrem Weg steht. Dieser Angriff ignoriert Rüstung, durchdringt aber nicht Permafrost." }
entries[65920] = { ["name"] = "Verfolgende Stacheln", ["text"] = "Sofort\nRammt einen Stachel durch den Boden, der alle Ziele im Umkreis von 4 Metern aufspießt, 2828 to 3172 Schaden verursacht und sie in die Luft schleudert. Dieser Angriff ignoriert Rüstung." }
entries[65921] = { ["name"] = "Verfolgende Stacheln" }
entries[65922] = { ["name"] = "Verfolgende Stacheln", ["text"] = "Sofort\nRammt einen Stachel durch den Boden, der alle Ziele im Umkreis von 4 Metern aufspießt, 2828 to 3172 Schaden verursacht und sie in die Luft schleudert. Dieser Angriff ignoriert Rüstung." }
entries[65923] = { ["name"] = "Verfolgende Stacheln", ["text"] = "Sofort\nRammt einen Stachel durch den Boden, der alle Ziele im Umkreis von 4 Metern aufspießt, 2828 to 3172 Schaden verursacht und sie in die Luft schleudert. Dieser Angriff ignoriert Rüstung." }
entries[65924] = { ["name"] = "Überwältigen", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nSofortige Überwältigung des Feindes, wodurch Waffenschaden plus 35 entsteht. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[65925] = { ["name"] = "Unerbittliche Gewalt", ["text"] = "Nahkampfreichweite\nSofort\nWenn Ihr einen Spieler mit 'Überwältigen' trefft, während er einen Zauber wirkt, wird sein Zauberschaden und seine Heilung 6 sec lang um 50% verringert." }
entries[65926] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin heimtückischer Stoß, der Waffenschaden plus 1000 verursacht und das Ziel verwundet sowie die Wirksamkeit jeglicher Heilung 10 sec lang um 50% verringert." }
entries[65927] = { ["name"] = "Sturmangriff", ["text"] = "8 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nStürmt einen Feind an und betäubt ihn 1.50 sec lang." }
entries[65929] = { ["name"] = "Sturmangriffbetäubung", ["text"] = "8 - 25 Meter Reichweite\nSofort\nStürmt einen Feind an und betäubt ihn 1.50 sec lang." }
entries[65930] = { ["name"] = "Drohruf", ["text"] = "8 Meter Reichweite\nSofort 2 min Abklingzeit\nDer Krieger schreit, woraufhin Feinde in einem Umkreis von 8 Metern 8 sec lang vor Angst erstarren." }
entries[65931] = { ["name"] = "Drohruf", ["text"] = "15 Meter Reichweite\nSofort\nDer Krieger schreit, woraufhin ein Feind 8 sec lang vor Angst erstarrt." }
entries[65932] = { ["name"] = "Gegenschlag", ["text"] = "Sofort 5 min Abklingzeit\nEin sofortiger Gegenangriff gegen jeden Feind, der Euch im Nahkampf schlägt. Hält 12 sec lang an. Bei Nahkampfangriffen, die von hinten geführt werden, ist ein Gegenangriff nicht möglich. Maximal 20 Angriffe können 'Gegenschlag' auslösen." }
entries[65934] = { ["name"] = "Gegenschlag", ["text"] = "Nahkampfreichweite\nSofort\nEin sofortiger Gegenangriff gegen jeden Feind, der Euch im Nahkampf schlägt. Hält 12 sec lang an. Bei Nahkampfangriffen, die von hinten geführt werden, ist ein Gegenangriff nicht möglich. Maximal 20 Angriffe können 'Gegenschlag' auslösen." }
entries[65935] = { ["name"] = "Entwaffnen", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nEntwaffnet 10 sec lang die Waffenhand- und Distanzwaffe des Gegners." }
entries[65936] = { ["name"] = "Rüstung zerreißen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung des Ziels, verringert sie pro Einsatz von 'Rüstung zerreißen' um 4% und verursacht ein hohes Maß an Bedrohung. Die Bedrohung wird durch Angriffskraft erhöht. Kann bis zu 5-mal angewendet werden. Hält 30 sec lang an." }
entries[65937] = { ["name"] = "Creature - Emote - Belch" }
entries[65940] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter ReichweiteWirken in 1.5 sek. 5 min Abklingzeit\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind, verursacht Waffenschaden, verringert die Rüstung des Ziels 10 sec lang um 20% oder entfernt jegliche Unverwundbarkeitseffekte." }
entries[65941] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind, verursacht 1 Schaden, verringert die Rüstung des Ziels 10 sec lang um 20% oder entfernt jegliche Unverwundbarkeitseffekte." }
entries[65946] = { ["name"] = "Klingensturm", ["text"] = "Sofort\nBenötigt Nahkampfwaffe\nIn einem stählernen Wirbel greift Ihr Feinde in einem Umkreis von 8 Metern an und verursacht 50% Waffenschaden." }
entries[65947] = { ["name"] = "Klingensturm", ["text"] = "Sofort 1.5 min Abklingzeit\nBenötigt Nahkampfwaffe\nGreift sofort alle nahen Ziele an. Für die nächsten 8 sec werdet Ihr alle 1 Sek. einen Wirbelwindangriff durchführen. Während 'Klingensturm' aktiv ist, könnt Ihr Euch bewegen, aber während dieser Zeit keine anderen Fähigkeiten einsetzen. Ihr fühlt weder Mitleid, noch Bedauern oder Furcht und es gibt keine Möglichkeit, Euch aufzuhalten, es sei denn, Ihr werdet getötet." }
entries[65949] = { ["name"] = "Schnelligkeit der Val'kyr", ["text"] = "Sofort\nDie Macht der Zwillinge erhöht 15 sec lang das Angriffstempo um 10%. Stapelbar." }
entries[65950] = { ["name"] = "Berührung des Lichts", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Val'kyr hat Euch mit ihrer Berührung des Lichts belegt, die Spielern, die unter dem Effekt der Essenz der Nacht stehen, alle 2 Sek. 5850 to 6150 Lichtschaden zufügt. Die Berührung des Lichts wird helle Ziele nicht verletzen." }
entries[65954] = { ["name"] = "Blutsturz", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 110% Waffenschaden sowie einen Blutsturz beim Ziel verursacht und so den dem Ziel zugefügten körperlichen Schaden um bis zu 75 erhöht. Hält 10 Aufladungen oder 15 sec lang an. Gewährt 1 Combopunkt." }
entries[65955] = { ["name"] = "Dolchfächer", ["text"] = "30 Energie\nSofort 2 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWirft sofort beide Waffen auf alle Ziele innerhalb von 10 Metern und verursacht 90% Waffenschaden." }
entries[65956] = { ["name"] = "Klingenwirbel", ["text"] = "Sofort 2 min Abklingzeit\nErhöht Euer Angriffstempo um 20%. Zusätzlich treffen Angriffe einen weiteren in der Nähe befindlichen Gegner. Hält 15 sec lang an.\n(100ms Abklingzeit)" }
entries[65957] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nFinishing-Move, der 8750 to 11250 körperlichen Schaden verursacht." }
entries[65960] = { ["name"] = "Blenden", ["text"] = "30 Energie 20 Meter Reichweite\nSofort 2 min Abklingzeit\nBlendet das Ziel und lässt es bis zu 10 sec lang desorientiert umherlaufen. Jeglicher erlittene Schaden wird den Effekt aufheben." }
entries[65961] = { ["name"] = "Mantel der Schatten", ["text"] = "Sofort 1.5 min Abklingzeit\nBannt sofort alle schädlichen Zaubereffekte und erhöht Eure Chance, jeder Art von Zauber zu widerstehen, 5 sec lang um 90%. Effekte, die die Benutzung von 'Mantel der Schatten' verhindern, werden nicht entfernt." }
entries[65962] = { ["name"] = "Wundgift", ["text"] = "Nahkampfreichweite\nSofort\nVergiftet den Feind und verringert alle auf ihn angewandten Heileffekte 15 sec lang um 50%." }
entries[65970] = { ["name"] = "Sturmschlag", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort 8 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich werden die nächsten 4 Quellen des Naturschadens, der dem Ziel zugefügt wird, um 20% erhöht. Hält 12 sec lang an." }
entries[65971] = { ["name"] = "Sturmschlag", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich wird der dem Ziel zugefügte Naturschaden um 20% erhöht. Hält 12 sec lang an." }
entries[65972] = { ["name"] = "Sturmschlag", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort mit beiden Waffen an. Zusätzlich wird der dem Ziel zugefügte Naturschaden um 20% erhöht. Hält 12 sec lang an." }
entries[65973] = { ["name"] = "Erdschock", ["text"] = "18% von Grundmana 25 Meter Reichweite\nSofort 6 sek. Abklingzeit\nSchockt das Ziel unmittelbar mit erschütternder Kraft und verursacht 3213 to 3387 Naturschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 2 sec lang, dass diese Art Zauber gewirkt werden kann." }
entries[65974] = { ["name"] = "Lavapeitsche", ["text"] = "4% von Grundmana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nLädt Eure Schildhandwaffe mit Lava auf, verursacht sofort 100% Waffenschaden der Schildhandwaffe. Der Schaden ist um 25% erhöht, wenn Eure Schildhandwaffe mit 'Flammenzunge' verzaubert ist." }
entries[65975] = { ["name"] = "Windzorn", ["text"] = "(Procchance: 25%, 1s Abklingzeit)" }
entries[65976] = { ["name"] = "Windzorn", ["text"] = "100 Meter Reichweite\nSofort\nMit der Macht des Windes erfüllt, schlägt schnell 2 zusätzliche Male zu.\n(1s Abklingzeit)" }
entries[65978] = { ["name"] = "Flammenzungenangriff", ["text"] = "Unbegrenzte Reichweite\nSofort\nErfüllt die Waffe des Schamanen mit Feuermagie, erhöht den gesamten Zauberschaden. Jeder Treffer fügt zusätzlichen Feuerschaden zu, abhängig vom Waffentempo. Langsamere Waffen verursachen mehr Feuerschaden pro Schwung. Hält 30 Minuten lang an." }
entries[65979] = { ["name"] = "Waffe der Flammenzunge", ["text"] = "(Procchance: 50%, 500ms Abklingzeit)" }
entries[65980] = { ["name"] = "Kampfrausch", ["text"] = "750 Mana 20 Meter Reichweite\nSofort 10 min Abklingzeit\nErhöht Nahkampf-, Distanzangriffs- und Zaubertempo aller Gruppenmitglieder um 30%. Hält 40 sec lang an." }
