entries[65986] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Sofort\nVerringert die Zauberzeit Eures nächsten Wirkens von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung', 'Welle der Heilung' oder 'Kettenheilung' um 20%." }
entries[65987] = { ["name"] = "Blitzschlag", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nDeckt einen Feind mit Blitzschlägen ein und fügt ihm 6375 to 8625 Naturschaden zu." }
entries[65988] = { ["name"] = "Waffe des Mahlstroms", ["text"] = "Wenn Ihr mit einer Nahkampfwaffe Schaden verursacht, besteht eine Chance, dass die Zauberzeit Eures nächsten Wirkens von 'Blitzschlag', 'Kettenblitzschlag', 'Geringe Welle der Heilung', 'Kettenheilung' oder 'Welle der Heilung' um 1% verringert wird. Bis zu 5-mal stapelbar.\n(Procchance: 15%)" }
entries[65989] = { ["name"] = "Totem der Erdung", ["text"] = "5% von Grundmana\nSofort 15 sek. Abklingzeit\nBeschwört ein Totem der Erdung mit 5 Gesundheit zu Füßen des Zaubernden, das einen schädlichen Zauber, der auf ein in der Nähe befindliches Gruppenmitglied gewirkt wurde, auf das Totem umleitet und es zerstört. Zauber mit Flächenwirkung werden nicht umgeleitet. Hält 45 sec lang an." }
entries[65990] = { ["name"] = "Totem des Windzorns", ["text"] = "11% von Grundmana\nSofort\nBeschwört ein Totem des Windzorns mit 5 Gesundheit zu Füßen des Zaubernden. Das Totem erhöht das Nahkampfangriffstempo aller Gruppen- und Schlachtzugsmitglieder im Umkreis von 30 Metern um 16%. Hält 5 min lang an." }
entries[65991] = { ["name"] = "Totem der Erdstärke", ["text"] = "10% von Grundmana\nSofort\nBeschwört ein Totem der Erdstärke mit 5 Gesundheit zu Füßen des Zaubernden. Die Stärke und Beweglichkeit aller Gruppen- und Schlachtzugsmitglieder in einem Umkreis von 30 Metern wird um 155 erhöht. Hält 5 min lang an." }
entries[65992] = { ["name"] = "Totem des Erdstoßes", ["text"] = "2% von Grundmana\nSofort\nBeschwört ein Totem des Erdstoßes mit 5 Gesundheit zu Füßen des Zaubernden, das den Boden erschüttert und Furcht-, Schlaf- und Bezauberungseffekte von Gruppenmitgliedern im Umkreis von 30 Metern entfernt. Hält 5 min lang an." }
entries[65993] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "30 Meter Reichweite\nSofort\nStellt 20813 to 24187 Gesundheit von nahen Verbündeten wieder her." }
entries[65994] = { ["name"] = "Heilender Fluss", ["text"] = "Stellt alle 2 Sek. Gesundheit her." }
entries[65995] = { ["name"] = "Totem des heilenden Flusses", ["text"] = "3% von Grundmana\nSofort\nBeschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden. Gruppenmitglieder im Umkreis von 40 Metern erhalten alle 2 Sek. 20813 to 24187 Gesundheit. Hält 5 min lang an." }
entries[65997] = { ["name"] = "Totem der Verbrennung", ["text"] = "15% von Grundmana\nSofort\nBeschwört für 30 sec ein Totem der Verbrennung mit 1 Gesundheit zu Euren Füßen, das wiederholt 3 Feinde im Umkreis von 40 Metern angreift und 1980 to 2420 Feuerschaden anrichtet." }
entries[65998] = { ["name"] = "Angreifen", ["text"] = "40 Meter Reichweite\nWirken in 2.2 sek.\nVersengt das Ziel mit 4950 to 6050 Feuerschaden." }
entries[66001] = { ["name"] = "Berührung der Nacht", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Val'kyr hat Euch mit ihrer Berührung der Nacht belegt, die Spielern, die unter dem Effekt der Essenz des Lichts stehen, alle 2 Sek. 5850 to 6150 Nachtschaden zufügt. Die Berührung der Nacht wird dunkle Ziele nicht verletzen." }
entries[66003] = { ["name"] = "Kreuzfahrerstoß", ["text"] = "8% von Grundmana Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 110% Waffenschaden verursacht." }
entries[66004] = { ["name"] = "Siegel des Befehls", ["text"] = "90 Mana\nSofort\nAlle Nahkampfangriffe haben eine Chance, zusätzlichen Heiligschaden zu verursachen." }
entries[66005] = { ["name"] = "Richturteil des Befehls", ["text"] = "20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nRichtet den Feind für 8550 to 9450 Heiligschaden." }
entries[66006] = { ["name"] = "Göttlicher Sturm", ["text"] = "12% von Grundmana\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin sofortiger Waffenangriff, der bei bis zu 4 Feinden innerhalb von 8 Metern 110% Waffenschaden verursacht." }
entries[66007] = { ["name"] = "Hammer der Gerechtigkeit", ["text"] = "3% von Grundmana 15 Meter Reichweite\nSofort 40 sek. Abklingzeit\nBetäubt das Ziel 6 sec lang." }
entries[66008] = { ["name"] = "Buße", ["text"] = "9% von Grundmana 20 Meter Reichweite\nSofort 1 min Abklingzeit\nVersetzt das feindliche Ziel in einen meditativen Zustand, macht es so bis zu 10 sec lang handlungsunfähig. Jeglicher erlittene Schaden wird das Ziel wecken. Wirkt auf Dämonen, Drachkin, Riesen, Humanoide und Untote." }
entries[66009] = { ["name"] = "Hand des Schutzes", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort 5 min Abklingzeit\nEin anvisiertes Bündnismitglied ist 10 sec lang vor allen körperlichen Angriffen geschützt." }
entries[66010] = { ["name"] = "Gottesschild", ["text"] = "3% von Grundmana\nSofort 5 min Abklingzeit\nSchützt den Paladin 12 sec lang vor allen Schäden und Zaubern, verringert jedoch seinen verursachten Schaden um 50%. Einmal geschützt, kann der Paladin 2 min lang nicht erneut durch 'Gottesschild', 'Göttlicher Schutz' oder 'Hand des Schutzes' geschützt werden. Kann innerhalb von 30 sec nach 'Zornige Vergeltung' nicht genutzt werden." }
entries[66011] = { ["name"] = "Zornige Vergeltung", ["text"] = "8% von Grundmana\nSofort 3 min Abklingzeit\nErhöht jeglichen verursachten Schaden und Heilung 20 sec lang um 20%. Kann, nachdem man Ziel von 'Gottesschild', 'Göttlicher Schutz' oder 'Hand des Schutzes' war, 30 sec lang nicht genutzt werden." }
entries[66012] = { ["name"] = "Gefrierender Streich", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 25% Frostschlagschaden zu und hüllt ihn 3 sec lang in einen Eisblock." }
entries[66013] = { ["name"] = "Durchdringende Kälte", ["text"] = "Sofort\nDurchdringende Kälte peinigt mehrere feindliche Ziele und verursacht alle 3 Sek. 6000 Frostschaden. Hält 18 sec lang an." }
entries[66017] = { ["name"] = "Todesgriff", ["text"] = "30 Meter Reichweite\nSofort 35 sek. Abklingzeit\nNutzt die Mächte unheiliger Energien, die alle Materie umgibt und bindet, um das Ziel zum Todesritter hin zu ziehen und es zu zwingen, ihn 3 sec lang anzugreifen." }
entries[66018] = { ["name"] = "Strangulieren", ["text"] = "30 Meter Reichweite\nSofort 2 min Abklingzeit\nWürgt einen Feind und bringt ihn bis zu 5 sec lang zum Schweigen. Endet der Effekt, erleidet das Ziel 180 Schattenschaden." }
entries[66019] = { ["name"] = "Todesmantel", ["text"] = "30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nEntfesselt unheilige Energien, die einem feindlichen Ziel 6475 to 7525 Schattenschaden zufügen oder ein befreundetes untotes Ziel um 9713 Gesundheit heilen." }
entries[66020] = { ["name"] = "Eisketten", ["text"] = "25 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUmschlingt das Ziel mit eisigen Ketten und verringert sein Bewegungstempo auf 5% des Normalwerts. Nach dem Ausbruch aus den Ketten erhält das Ziel 10 sec lang pro Sekunde 10% seines Bewegungstempos zurück." }
entries[66021] = { ["name"] = "Eisige Berührung", ["text"] = "20 Meter Reichweite\nSofort 8 sek. Abklingzeit\nUnterkühlt das Ziel für 5272 bis 5728 Frostschaden und steckt es mit Frostfieber an, einer Krankheit, die regelmäßig Schaden verursacht und 15 sec lang das Nahkampf- und Distanzangriffstempo des Ziels um 14% verringert." }
entries[66023] = { ["name"] = "Eisige Gegenwehr", ["text"] = "Sofort 1 min Abklingzeit\nDer Todesritter bringt sein Blut zum Gefrieren, um immun gegenüber Betäubungseffekten zu werden und jeglichen erlittenen Schaden um 45% zu verringern. Hält 12 sec lang an." }
entries[66030] = { ["name"] = "Gurgli", ["text"] = "Sofort\nMit Rechtsklick Gurgli den Murloc-Marine beschwören und freigeben." }
entries[66034] = { ["name"] = "Kandierte Süßkartoffel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSüßkartoffel aus Mulgore , Honig , Herbstliche Gewürze\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Tempowertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[66035] = { ["name"] = "Moosbeerenchutney", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSäuerliche Moosbeeren vom Südstrom , Honig\n(0)\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Zaubermacht um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[66036] = { ["name"] = "Kürbiskuchen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nReifer Tirisfalkürbis , Honig\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[66037] = { ["name"] = "Langsam gerösteter Truthahn", ["text"] = "Wirken in 2 sek.\nReagenzien:\nWilder Truthahn , Honig (2), Herbstliche Gewürze\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Angriffskraft um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
entries[66038] = { ["name"] = "Gewürzbrotfüllung", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGewürzbrot , Herbstliche Gewürze\nDauer: 7 tagen (Realzeit)\nBenutzen: Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 hour lang Eure Trefferwertung und Ausdauer um [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] erhöht.", ["unresolvedValues"] = true }
