entries[66098] = { ["name"] = "Sühne", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert eine Salve heiligen Lichts auf das Ziel, die ein freundliches Ziel sofort um 42255 to 47745 heilt sowie 2 sec lang alle 1 Sek." }
entries[66099] = { ["name"] = "Machtwort: Schild", ["text"] = "500 Mana 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 67063 to 77937 Schaden. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[66100] = { ["name"] = "Manabrand", ["text"] = "14% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 10 sek. Abklingzeit\nZerstört 4374 to 4626 Mana des Ziels. Für jedes auf diese Weise zerstörte Mana erleidet das Ziel 3 Schattenschaden." }
